import re

# Module constants use only allowed pure expressions.
_WORD_RE = re.compile(r"[A-Z][A-Za-z0-9''\-]*")
_TITLE_RE = re.compile(r"\[TLE\]")
_DOC_RE = re.compile(r"\[DOC\]")
_STOP = frozenset(
    ["The", "A", "An", "And", "But", "For", "With", "From", "Into", "After",
     "Before", "During", "This", "That", "These", "Those", "His", "Her",
     "Their", "Its", "Was", "Were", "Is", "Are", "Has", "Have", "Had",
     "Not", "One", "Two", "Both", "All", "Some", "When", "Where", "While",
     "About", "Directed", "Starring", "Create", "Download", "Printable",
     "Version", "See", "More", "Jeans"]
)


def applies(view):
    # Only fires when there is context text with document markers.
    context = view.get("context") or ""
    question = view.get("question") or ""
    return bool(context) and bool(question)


def _question_lower_words(question):
    return set(question.lower().split())


def _snippet_texts(context):
    parts = _DOC_RE.split(context)
    texts = []
    for part in parts:
        part = part.strip()
        if not part:
            continue
        texts.append(part)
    return texts


def _extract_phrases(text):
    words = _WORD_RE.findall(text)
    phrases = set()
    n = len(words)
    for i in range(n):
        if words[i] in _STOP:
            continue
        phrases.add(words[i])
        if i + 1 < n and words[i + 1] not in _STOP:
            phrases.add(words[i] + " " + words[i + 1])
        if i + 2 < n and words[i + 1] not in _STOP and words[i + 2] not in _STOP:
            phrases.add(words[i] + " " + words[i + 1] + " " + words[i + 2])
    return phrases


def before_call(view, state):
    context = view.get("context") or ""
    question = view.get("question") or ""
    if not context or not question:
        return None

    q_words = _question_lower_words(question)
    snippets = _snippet_texts(context)
    if not snippets:
        return None

    counts = {}
    for snippet in snippets:
        phrases = _extract_phrases(snippet)
        for phrase in phrases:
            low = phrase.lower()
            if any(w in q_words for w in low.split()):
                continue
            counts[phrase] = counts.get(phrase, 0) + 1

    # Keep only phrases found in more than one snippet.
    multi = {p: c for p, c in counts.items() if c >= 2}
    if not multi:
        return None

    ranked = sorted(multi.items(), key=lambda kv: (-kv[1], kv[0]))
    top = ranked[:5]

    candidates = []
    for phrase, cnt in top:
        entry = (phrase + " (" + str(cnt) + " snippets)")[:120]
        candidates.append(entry)

    facts = []
    for phrase, cnt in top:
        fact = ("Capitalized phrase present in " + str(cnt) + " of " +
                str(len(snippets)) + " snippets: " + phrase)[:200]
        facts.append(fact)

    notes = {}
    if facts:
        notes["facts"] = facts
    if candidates:
        notes["candidates"] = candidates
    if not notes:
        return None
    return notes
